const ticker = $('Loop Over Coin Pairs').first().json;

const candles = $input.all().map(item => {
  const c = item.json;
  return {
    openTime:      Number(c[0]),
    open:          parseFloat(c[1]),
    high:          parseFloat(c[2]),
    low:           parseFloat(c[3]),
    close:         parseFloat(c[4]),
    volume:        parseFloat(c[5]),    // Base asset volume
    quoteVol:      parseFloat(c[7]),    // Quote volume (USDT)
    trades:        parseInt(c[8]),
    takerBuyBase:  parseFloat(c[9]),    // Taker buy base volume
    takerBuyQuote: parseFloat(c[10]),   // Taker buy quote volume (USDT)
  };
});

// ── Most recent closed candle (index -2) ──
// Index -1 = currently forming candle (not yet closed) → skip
const lastClosed = candles[candles.length - 2];

// 24 candles before the closed candle (index 0 → index -3)
const previous = candles.slice(0, -2);

// ── Volume Spike Ratio ──
// Use trimmed mean (remove top/bottom 10% outliers before averaging)
const sortedVols = previous.map(c => c.quoteVol).sort((a, b) => a - b);
const trimCount = Math.round(sortedVols.length * 0.1);
const trimmedVols = sortedVols.slice(trimCount, sortedVols.length - trimCount);
const avgVol1h = trimmedVols.reduce((s, v) => s + v, 0) / trimmedVols.length;

const sortedTrades = previous.map(c => c.trades).sort((a, b) => a - b);
const trimCountT = Math.round(sortedTrades.length * 0.1);
const trimmedTrades = sortedTrades.slice(trimCountT, sortedTrades.length - trimCountT);
const avgTrades1h = trimmedTrades.reduce((s, v) => s + v, 0) / trimmedTrades.length;

const volRatio   = avgVol1h > 0
  ? parseFloat((lastClosed.quoteVol / avgVol1h).toFixed(2)) : 0;
const tradeRatio = avgTrades1h > 0
  ? parseFloat((lastClosed.trades / avgTrades1h).toFixed(2)) : 0;

// ── Taker Buy/Sell Ratio ──
// takerBuyQuote = aggressive buy volume (market buys)
// takerSellQuote = total volume - taker buy = aggressive sell volume
const takerBuyPct = lastClosed.quoteVol > 0
  ? parseFloat((lastClosed.takerBuyQuote / lastClosed.quoteVol * 100).toFixed(1)) : 50;
const takerSellPct = parseFloat((100 - takerBuyPct).toFixed(1));

// Classify pressure
let pressure = 'NEUTRAL';
if (takerBuyPct >= 65) pressure = 'STRONG_BUY';
else if (takerBuyPct >= 55) pressure = 'BUY';
else if (takerBuyPct <= 35) pressure = 'STRONG_SELL';
else if (takerBuyPct <= 45) pressure = 'SELL';

// ── Price Action ──
const priceChange = parseFloat(
  ((lastClosed.close - lastClosed.open) / lastClosed.open * 100).toFixed(2)
);
const candleRange = parseFloat(
  ((lastClosed.high - lastClosed.low) / lastClosed.low * 100).toFixed(2)
);
const isBullish = lastClosed.close >= lastClosed.open;

// Candle body vs wick ratio (large body = momentum, long wick = rejection)
const bodySize = Math.abs(lastClosed.close - lastClosed.open);
const totalRange = lastClosed.high - lastClosed.low;
const bodyRatio = totalRange > 0
  ? parseFloat((bodySize / totalRange * 100).toFixed(0)) : 0;
// bodyRatio > 60% = strong momentum candle
// bodyRatio < 30% = doji/indecision

// ── Multi-candle Context ──
// Check if the 3 candles before the spike have rising volume
const last3 = previous.slice(-3).map(c => c.quoteVol);
const volTrend =
  last3.every((v, i) => i === 0 || v >= last3[i-1] * 0.9) ? 'RISING' :
  last3.every((v, i) => i === 0 || v <= last3[i-1] * 1.1) ? 'FALLING' : 'MIXED';

// Did the previous candle also spike? (sustained volume)
const prevCandle = candles[candles.length - 3];
const prevVolRatio = avgVol1h > 0
  ? parseFloat((prevCandle.quoteVol / avgVol1h).toFixed(2)) : 0;
const sustainedSpike = prevVolRatio >= 1.5; // Previous candle also abnormally high

// ── Spike Classification ──
// ── with dedup ──
let spikeType = 'NONE';
if (volRatio >= 5)        spikeType = 'EXTREME';
else if (volRatio >= 3.5) spikeType = 'VERY_HIGH';
else if (volRatio >= 2.5) spikeType = 'HIGH';

// ── Dedup Check ──
const COOLDOWN_HOURS = 4;
const staticData = $getWorkflowStaticData('global');
if (!staticData.lastAlerted) staticData.lastAlerted = {};

const now = Date.now();
const lastTime = staticData.lastAlerted[ticker.symbol] || 0;
const hoursSinceLast = (now - lastTime) / (1000 * 60 * 60);

if (spikeType !== 'NONE' && hoursSinceLast < COOLDOWN_HOURS) {
  spikeType = 'NONE';
}

if (spikeType !== 'NONE') {
  staticData.lastAlerted[ticker.symbol] = now;
}

return [{
  json: {
    // Ticker data
    symbol:     ticker.symbol,
    price:      ticker.price,
    change24h:  ticker.change24h,
    volume24h:  ticker.volume24h,

    // Spike metrics
    volRatio,
    tradeRatio,
    spikeType,
    avgVol1h:      parseFloat(avgVol1h.toFixed(0)),
    currentVol1h:  parseFloat(lastClosed.quoteVol.toFixed(0)),

    // Taker buy/sell data
    takerBuyPct,
    takerSellPct,
    pressure,

    // Price action
    priceChange,
    candleRange,
    isBullish,
    bodyRatio,

    // Multi-candle context
    volTrend,
    prevVolRatio,
    sustainedSpike,

    // Timestamp
    detectedAt: new Date().toISOString(),
  }
}];

const spike = $('Compute Volume Spike').first().json;
const book = $input.first().json;

// Parse order book
const bids = book.bids.map(b => ({
  price: parseFloat(b[0]),
  qty:   parseFloat(b[1]),
}));
const asks = book.asks.map(a => ({
  price: parseFloat(a[0]),
  qty:   parseFloat(a[1]),
}));

// Top 5 bid/ask volume (USDT)
const bidVol5 = bids.slice(0, 5).reduce((s, b) => s + b.price * b.qty, 0);
const askVol5 = asks.slice(0, 5).reduce((s, a) => s + a.price * a.qty, 0);

// Top 20 bid/ask volume (USDT)
const bidVol20 = bids.reduce((s, b) => s + b.price * b.qty, 0);
const askVol20 = asks.reduce((s, a) => s + a.price * a.qty, 0);

// Bid/Ask ratio
const bookRatio5  = askVol5 > 0
  ? parseFloat((bidVol5 / askVol5).toFixed(2)) : 0;
const bookRatio20 = askVol20 > 0
  ? parseFloat((bidVol20 / askVol20).toFixed(2)) : 0;

// Spread
const bestBid = bids[0]?.price || 0;
const bestAsk = asks[0]?.price || 0;
const spreadPct = bestAsk > 0
  ? parseFloat(((bestAsk - bestBid) / bestAsk * 100).toFixed(4)) : 0;

// Book pressure classification
let bookPressure = 'BALANCED';
if (bookRatio5 >= 2.0) bookPressure = 'STRONG_BID_WALL';
else if (bookRatio5 >= 1.3) bookPressure = 'BID_HEAVY';
else if (bookRatio5 <= 0.5) bookPressure = 'STRONG_ASK_WALL';
else if (bookRatio5 <= 0.77) bookPressure = 'ASK_HEAVY';

return [{
  json: {
    // All spike data
    ...spike,

    // Order book data
    bidVol5:      parseFloat(bidVol5.toFixed(0)),
    askVol5:      parseFloat(askVol5.toFixed(0)),
    bookRatio5,
    bookRatio20,
    spreadPct,
    bookPressure,
  }
}];

const d = $input.first().json;

const staticData = $getWorkflowStaticData('global');
const market = staticData.marketContext || { btcChange: 0, ethChange: 0 };

const systemPrompt = `You are a crypto market analyst specializing in volume analysis.

Task: Analyze the volume spike data and determine what it likely means for the coin's short-term price action.

Analysis framework:
1. Assess spike significance (how unusual is this volume?)
2. Taker buy ratio: >60% = real buying pressure, <40% = selling pressure, 45-55% = inconclusive
3. If taker buy is low + volume spike + price drop = likely panic selling or whale dumping
4. If taker buy is high + volume spike + price up = likely breakout or accumulation
5. Order book: treat as weak signal only — walls can be spoofed. Never let book pressure override taker buy/sell ratio or price action. Only mention book data as supporting context, not as primary evidence
6. Sustained spike (previous candle also high volume) = stronger signal than single candle spike
7. Body ratio: >60% = strong momentum, <30% = rejection/indecision despite high volume
8. Give a short-term outlook (next 4-24 hours)

IMPORTANT RULES:
- High volume + low taker buy (<40%) + price dropping = BEARISH_DUMP, NOT accumulation
- High volume + small price change + taker buy near 50% = possible wash trading, classify as UNCERTAIN
- Sustained spike (prevVolRatio >= 1.5) increases confidence by +0.1
- Ask wall (bookPressure = ASK_HEAVY or STRONG_ASK_WALL) with bullish spike = reduce confidence, add resistance warning
- Spread > 0.5% = low liquidity warning
- If BTC drops more than 3%, most altcoin spikes are market-wide panic, not coin-specific events. Lower confidence for BULLISH classifications.
- If BTC and ETH both move in the same direction more than 2%, treat altcoin spikes as correlated market movement unless the altcoin's move is 3x stronger than BTC's.

Classification:
- BULLISH_BREAKOUT: High volume + price rising + taker buy >55% + no major ask wall
- BEARISH_DUMP: High volume + price dropping + taker buy <45%
- ACCUMULATION: High volume + small price change (<1%) + taker buy >55% + bid wall present
- DISTRIBUTION: High volume + price near highs + taker buy <45% + ask wall present
- UNCERTAIN: Conflicting signals or possible wash trading

Output ONLY valid JSON:
{
  "classification": "BULLISH_BREAKOUT | BEARISH_DUMP | ACCUMULATION | DISTRIBUTION | UNCERTAIN",
  "severity": "LOW | MEDIUM | HIGH | CRITICAL",
  "summary": "<2-3 sentence explanation referencing taker ratio and book pressure>",
  "action": "<what a trader should watch for next>",
  "confidence": <0.0-1.0>,
  "entryZone": "<price range to watch for entry, e.g. $0.45-$0.47, based on nearest support for longs or resistance for shorts>",
  "invalidation": "<price level that invalidates this signal, e.g. below $0.42>",
  "timeframe": "<expected timeframe: 1-4h or 4-24h>"
}`;

const userPrompt = `Analyze this volume spike:

SYMBOL: ${d.symbol}
Current Price: $${d.price}
24h Change: ${d.change24h}%

VOLUME SPIKE:
├ Current 1h Volume: $${d.currentVol1h.toLocaleString()}
├ Avg 1h Volume (24h): $${d.avgVol1h.toLocaleString()}
├ Volume Ratio: ${d.volRatio}x (${d.spikeType})
├ Trade Count Ratio: ${d.tradeRatio}x
├ Volume Trend (last 3h): ${d.volTrend}
├ Previous Candle Vol Ratio: ${d.prevVolRatio}x
└ Sustained Spike: ${d.sustainedSpike ? 'YES (prev candle also high)' : 'NO (single candle)'}

TAKER BUY/SELL ANALYSIS:
├ Taker Buy: ${d.takerBuyPct}%
├ Taker Sell: ${d.takerSellPct}%
└ Pressure: ${d.pressure}

PRICE ACTION:
├ 1h Change (open→close): ${d.priceChange}%
├ 1h Range (low→high): ${d.candleRange}%
├ Direction: ${d.isBullish ? 'BULLISH (close > open)' : 'BEARISH (close < open)'}
└ Body Ratio: ${d.bodyRatio}% ${d.bodyRatio > 60 ? '(strong momentum)' : d.bodyRatio < 30 ? '(rejection/doji)' : '(moderate)'}

ORDER BOOK (top 5 levels):
├ Bid Volume: $${d.bidVol5.toLocaleString()}
├ Ask Volume: $${d.askVol5.toLocaleString()}
├ Bid/Ask Ratio: ${d.bookRatio5}x
├ Pressure: ${d.bookPressure}
└ Spread: ${d.spreadPct}%

MARKET CONTEXT:
├ BTC 24h: ${market.btcChange > 0 ? '+' : ''}${market.btcChange}%
└ ETH 24h: ${market.ethChange > 0 ? '+' : ''}${market.ethChange}%

Return ONLY valid JSON.`;

return [{
  json: {
    ...d,
    systemPrompt,
    userPrompt,
  }
}];

const raw = $input.first().json;

// Handle different output formats from the OpenAI node in n8n
const text = raw.output?.[0]?.content?.[0]?.text
          || raw.message?.content
          || raw.choices?.[0]?.message?.content
          || JSON.stringify(raw);

let analysis;
try {
  const cleaned = text.replace(/```json|```/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch (e) {
  analysis = {
    classification: 'UNCERTAIN',
    severity: 'MEDIUM',
    summary: 'AI parse error: ' + e.message,
    action: 'Manual review needed',
    confidence: 0,
  };
}

const origin = $('Prepare AI Analysis Prompt').first().json;

return [{
  json: {
    // Spike data
    symbol:        origin.symbol,
    price:         origin.price,
    change24h:     origin.change24h,
    volRatio:      origin.volRatio,
    tradeRatio:    origin.tradeRatio,
    spikeType:     origin.spikeType,
    currentVol1h:  origin.currentVol1h,
    avgVol1h:      origin.avgVol1h,

    // Taker data
    takerBuyPct:   origin.takerBuyPct,
    takerSellPct:  origin.takerSellPct,
    pressure:      origin.pressure,

    // Price action
    priceChange:   origin.priceChange,
    candleRange:   origin.candleRange,
    isBullish:     origin.isBullish,
    bodyRatio:     origin.bodyRatio,

    // Context
    volTrend:      origin.volTrend,
    sustainedSpike: origin.sustainedSpike,

    // Order book
    bookRatio5:    origin.bookRatio5,
    bookPressure:  origin.bookPressure,
    spreadPct:     origin.spreadPct,
    bidVol5:       origin.bidVol5,
    askVol5:       origin.askVol5,

    // AI analysis
    classification: analysis.classification,
    severity:       analysis.severity,
    summary:        analysis.summary,
    action:         analysis.action,
    confidence:     analysis.confidence,
    entryZone:      analysis.entryZone || 'N/A',
    invalidation:   analysis.invalidation || 'N/A',
    timeframe:      analysis.timeframe || 'N/A',

    detectedAt: origin.detectedAt,
  }
}];

const item = $input.first().json;

// Store results in workflow static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.spikeResults) {
  staticData.spikeResults = [];
}
staticData.spikeResults.push(item);

return [{ json: { collected: staticData.spikeResults.length } }];

const TOP_TELEGRAM = 3;
const items = $input.all().map(i => i.json).slice(0, TOP_TELEGRAM);

if (!items.length || !items[0].symbol) {
  return [{ json: { message: null } }];
}

const emoji = {
  'BULLISH_BREAKOUT': '🟢🚀',
  'BEARISH_DUMP':     '🔴📉',
  'ACCUMULATION':     '🟡🐋',
  'DISTRIBUTION':     '🟠📤',
  'UNCERTAIN':        '⚪❓',
};

const medal = ['🥇', '🥈', '🥉'];
const sign = n => n > 0 ? '+' : '';

let message = `📡 <b>VOLUME SPIKE REPORT</b>\n`;
const hasCritical = items.some(d => d.severity === 'CRITICAL' || d.severity === 'HIGH');
if (hasCritical) {
  message += `🚨 <b>HIGH PRIORITY ALERT</b>\n`;
}
message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `${items.length} spike(s) detected this hour\n`;

items.forEach((d, i) => {
  const cls = emoji[d.classification] || '⚪';

  message += `${medal[i]} <b>${d.symbol}</b> ${cls}\n`;
  message += `├ Volume:  <code>${d.volRatio}x avg</code> (${d.spikeType})`;
  if (d.sustainedSpike) message += ` 🔄`;
  message += `\n`;
  message += `├ Taker:   <code>Buy ${d.takerBuyPct}%</code> → ${d.pressure}\n`;
  message += `├ Price:   <code>${sign(d.priceChange)}${d.priceChange}%</code> | Body: <code>${d.bodyRatio}%</code>\n`;
  message += `├ Book:    <code>${d.bookPressure}</code> (${d.bookRatio5}x)\n`;
  message += `├ AI:      <code>${d.classification.replace(/_/g, ' ')}</code> (${(d.confidence * 100).toFixed(0)}%)\n`;
  message += `├ Score:   <code>${d.rankScore}/100</code>\n`;
  message += `├ Entry:   <code>${d.entryZone}</code>\n`;
  message += `├ Invalid: <code>${d.invalidation}</code>\n`;
  message += `├ Time:    <code>${d.timeframe}</code>\n`;
  message += `└ <i>${d.summary}</i>\n\n`;
});

message += `🕐 ${new Date().toISOString()}`;

return [{ json: { message } }];

// ═══ CONFIG ═══
const TOP_TELEGRAM = 3;   // Number of coins to send via Telegram
const TOP_SHEETS   = 10;  // Number of coins to log to Google Sheets

// Get all collected spikes
const staticData = $getWorkflowStaticData('global');
let spikes = staticData.spikeResults || [];
staticData.spikeResults = []; // Reset for next run

if (spikes.length === 0) {
  return [[]];
}

// ══════════════════════════════════════════
// SCORING
// ══════════════════════════════════════════

const scored = spikes.map(s => {
  let score = 0;

  // 1. Volume Spike Strength (0-30)
  if (s.volRatio >= 5)        score += 30;
  else if (s.volRatio >= 3.5) score += 25;
  else if (s.volRatio >= 2.5) score += 18;

  if (s.tradeRatio >= 3)      score += 10;
  else if (s.tradeRatio >= 2) score += 7;
  else if (s.tradeRatio >= 1.5) score += 4;

  if (s.sustainedSpike) score += 8;

  // 2. Taker Pressure Clarity (0-20)
  const takerDeviation = Math.abs(s.takerBuyPct - 50);
  if (takerDeviation >= 20) score += 20;
  else if (takerDeviation >= 15) score += 15;
  else if (takerDeviation >= 10) score += 10;
  else if (takerDeviation >= 5)  score += 4;

  // 3. Price Action Quality (0-20)
  if (s.bodyRatio >= 70) score += 12;
  else if (s.bodyRatio >= 50) score += 8;
  else if (s.bodyRatio >= 30) score += 4;

  const absChange = Math.abs(s.priceChange);
  if (absChange >= 5) score += 8;
  else if (absChange >= 3) score += 6;
  else if (absChange >= 1) score += 3;

  // 4. AI Confidence (0-20)
  score += Math.round((s.confidence || 0) * 20);

  // 5. Penalties
  if (s.classification === 'UNCERTAIN') score -= 10;
  if (s.spreadPct > 0.5) score -= 5;
  if (s.volRatio >= 3 && s.tradeRatio < 1.2) score -= 8;

  return {
    ...s,
    rankScore: Math.max(0, score),
  };
});

// Sort by score descending
const sorted = scored.sort((a, b) => b.rankScore - a.rankScore);

// Tag: which go to Telegram, which are Sheets-only
const results = sorted.slice(0, Math.max(TOP_TELEGRAM, TOP_SHEETS)).map((s, i) => ({
  ...s,
  rank: i + 1,
  forTelegram: i < TOP_TELEGRAM,
  forSheets: i < TOP_SHEETS,
}));

return results.map(s => ({ json: s }));

// Flatten & order fields for Google Sheets logging
// Remove internal flags (forTelegram, forSheets, rank) and redundant fields

const items = $input.all();

return items.map(i => {
  const d = i.json;
  return { json: {
    // ── Timestamp & Identity ──
    detectedAt:     d.detectedAt,
    symbol:         d.symbol,
    price:          d.price,

    // ── AI Verdict ──
    classification: d.classification,
    severity:       d.severity,
    confidence:     d.confidence,
    rankScore:      d.rankScore,

    // ── Volume Spike ──
    spikeType:      d.spikeType,
    volRatio:       d.volRatio,
    tradeRatio:     d.tradeRatio,
    currentVol1h:   d.currentVol1h,
    avgVol1h:       d.avgVol1h,
    sustainedSpike: d.sustainedSpike,
    volTrend:       d.volTrend,

    // ── Taker Pressure ──
    takerBuyPct:    d.takerBuyPct,
    pressure:       d.pressure,

    // ── Price Action ──
    change24h:      d.change24h,
    priceChange:    d.priceChange,
    candleRange:    d.candleRange,
    isBullish:      d.isBullish,
    bodyRatio:      d.bodyRatio,

    // ── Order Book ──
    bookPressure:   d.bookPressure,
    bookRatio5:     d.bookRatio5,
    spreadPct:      d.spreadPct,

    // ── AI Details ──
    entryZone:      d.entryZone,
    invalidation:   d.invalidation,
    timeframe:      d.timeframe,
    summary:        d.summary,
    action:         d.action,
  }};
});

const items = $input.all();
const MIN_VOL = 10_000_000; // Min $10M volume 24h
const MIN_CHANGE = 1;       // Min 1% price change 24h

const allTickers = items.map(i => i.json);
const btc = allTickers.find(t => t.symbol === 'BTCUSDT');
const eth = allTickers.find(t => t.symbol === 'ETHUSDT');

const staticData = $getWorkflowStaticData('global');
staticData.marketContext = {
  btcChange: parseFloat(btc?.priceChangePercent || 0),
  ethChange: parseFloat(eth?.priceChangePercent || 0),
};

const stablecoins = [
  'USDCUSDT', 'BUSDUSDT', 'TUSDUSDT', 'DAIUSDT',
  'FDUSDUSDT', 'USDPUSDT', 'EURUSDT', 'GBPUSDT',
  'TRYUSDT', 'BRLUSDT', 'ARUSDT', 'USD1USDT',
  'RLUSDUSDT', 'UUSDT', 'XUSDUSDT', 'PYUSDUSDT',
  'CUSDUSDT', 'GUSDUSDT', 'SUSDUSDT',
];

const excludePatterns = [
/^(USD|EUR|GBP|AUD|TRY|BRL|JPY|KRW|IDR|NGN|ARS|PLN|RON|COP|ZAR).*USDT$/,
  /(UP|DOWN|BULL|BEAR)d*USDT$/,
  /^(LBTC|WBTC|WETH|STETH|RETH|CBETH|WBETH)USDT$/,
];

const filtered = items
  .map(i => i.json)
  .filter(t =>
    t.symbol.endsWith('USDT') &&
    !stablecoins.includes(t.symbol) &&
    !excludePatterns.some(p => p.test(t.symbol)) &&
    parseFloat(t.quoteVolume) > MIN_VOL &&
    Math.abs(parseFloat(t.priceChangePercent)) > MIN_CHANGE
  )
  .map(t => ({
    symbol: t.symbol,
    price: parseFloat(t.lastPrice),
    change24h: parseFloat(t.priceChangePercent),
    volume24h: parseFloat(t.quoteVolume),
    highPrice: parseFloat(t.highPrice),
    lowPrice: parseFloat(t.lowPrice),
    trades: parseInt(t.count),
  }));

return filtered.map(f => ({ json: f }));
